import base64,time,requests
BR2=(" elvo· brand system, bold and premium (think Apple/Dyson product page, NOT a generic ad): strong contrast and a rhythm of backgrounds, as specified; deep navy (#010A21), electric blue (#3355FF), steel blue (#9EBACE) and white; huge confident Inter-style headline (very few words), generous empty space, ONE idea per image; a large faint elvo· water-drop shape as a brand watermark in the background; small 'elvo·' wordmark in a corner; realistic product render with crisp reflections and a soft shadow, 1:1 square. ALL TEXT EXACTLY AS WRITTEN, Spanish with correct accents, nothing else added, no extra logos or fake badges. The purifier must look exactly like the first reference (white cylinder, grey water-drop icon, grey 'elvo' wordmark with its small drop, chrome swan-neck spout).")
def call(name,refs,p):
    for t in range(3):
        try:
            r=requests.post('https://queue.fal.run/openai/gpt-image-2/edit',json={'prompt':p+BR2,'image_urls':[g.uri(x) for x in refs],'image_size':{'width':1536,'height':1536},'quality':'high','num_images':1}).json()
            if 'status_url' not in r: print('ERR',name,str(r)[:200],flush=True); return
            while True:
                time.sleep(10); s=requests.get(r['status_url']).json()
                if s.get('status')=='COMPLETED': break
                if s.get('status') not in ('IN_QUEUE','IN_PROGRESS'): raise Exception(str(s)[:200])
            u=requests.get(r['response_url']).json()['images'][0]['url']
            open(F+name+'.png','wb').write(requests.get(u).content); print('saved',name,flush=True); return
        except Exception as e: print('retry',name,e,flush=True)
